import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function SellerProfile() {
    const navigate = useNavigate();
    const [profileData, setProfileData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        bio: '',
        profileImage: null
    });
    const [loading, setLoading] = useState(false);
    const [stats, setStats] = useState({
        posts: 0,
        followers: 0,
        following: 0,
        views: 0
    });
    const [reels, setReels] = useState([]);
    const [reelsLoading, setReelsLoading] = useState(false); // Changed to false by default
    const [showPosts, setShowPosts] = useState(false); // New state to control posts visibility

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Load actual user profile data from localStorage
        const loadUserProfile = () => {
            try {
                const storedUser = localStorage.getItem('studioUser');
                if (storedUser) {
                    const user = JSON.parse(storedUser);
                    setProfileData({
                        firstName: user.firstname || '',
                        lastName: user.lastname || '',
                        email: user.email || '',
                        phone: user.telephone || '',
                        bio: '', // Bio is not stored in the current user data
                        profileImage: null
                    });
                }
            } catch (error) {
                console.error('Error loading user profile:', error);
                toast.error('Failed to load profile data');
            }
        };
        
        loadUserProfile();
        loadSellerStats();
        // Don't load reels by default - only when user clicks on Posts
    }, []);

    const loadSellerStats = async () => {
        try {
            const storedUser = localStorage.getItem('studioUser');
            if (storedUser) {
                const user = JSON.parse(storedUser);
                const vendorId = user?.vendor_id || 1;
                
                const response = await ApiService.getSellerDashboardStats(vendorId);
                if (response.success) {
                    setStats({
                        posts: response.data.totalReels || 0,
                        followers: 0, // These would come from a different API in a real implementation
                        following: 0,
                        views: 0
                    });
                }
            }
        } catch (error) {
            console.error('Error loading seller stats:', error);
        }
    };

    // Function to load reels when user clicks on Posts
    const loadSellerReels = async () => {
        if (showPosts) return; // If already showing, don't reload
        
        try {
            setReelsLoading(true);
            const storedUser = localStorage.getItem('studioUser');
            if (storedUser) {
                const user = JSON.parse(storedUser);
                const vendorId = user?.vendor_id || 1;
                
                const response = await ApiService.getSellerReels(vendorId);
                if (response.success) {
                    setReels(response.data || []);
                }
            }
        } catch (error) {
            console.error('Error loading seller reels:', error);
            toast.error('Failed to load reels');
        } finally {
            setReelsLoading(false);
        }
    };

    const handlePostsClick = () => {
        setShowPosts(true);
        if (reels.length === 0) {
            loadSellerReels();
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setProfileData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setProfileData(prev => ({
                ...prev,
                profileImage: file
            }));
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        setLoading(true);
        
        try {
            // In a real implementation, this would send data to the backend
            // For now, we'll just show a success message
            setTimeout(() => {
                // Update localStorage with the new data
                try {
                    const storedUser = localStorage.getItem('studioUser');
                    if (storedUser) {
                        const user = JSON.parse(storedUser);
                        const updatedUser = {
                            ...user,
                            firstname: profileData.firstName,
                            lastname: profileData.lastName,
                            email: profileData.email,
                            telephone: profileData.phone
                        };
                        localStorage.setItem('studioUser', JSON.stringify(updatedUser));
                        toast.success('Profile updated successfully!');
                    }
                } catch (error) {
                    console.error('Error updating user profile:', error);
                    toast.error('Failed to update profile');
                }
            }, 1000);
        } catch (error) {
            console.error('Profile update error:', error);
            toast.error('Failed to update profile: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const renderReel = (reel) => {
        // Construct full URLs for video and thumbnail
        const baseUrl = window.location.origin;
        let fullThumbnailUrl = reel.thumbnail;
        
        // Handle relative URLs
        if (reel.thumbnail && !reel.thumbnail.startsWith('http')) {
            fullThumbnailUrl = `${baseUrl}${reel.thumbnail}`;
        }
        
        return (
            <div className="col-md-4 col-sm-6" key={reel.id}>
                <div className="card border">
                    <div className="position-relative">
                        {fullThumbnailUrl ? (
                            <img 
                                src={fullThumbnailUrl} 
                                alt={reel.title}
                                className="card-img-top" 
                                style={{ height: '200px', objectFit: 'cover' }}
                            />
                        ) : (
                            <div className="bg-light" style={{ height: '200px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                <i className="ri-image-line fs-1 text-muted"></i>
                            </div>
                        )}
                        <div className="position-absolute bottom-0 start-0 m-2">
                            <span className="badge bg-primary">{reel.category_name || 'Uncategorized'}</span>
                        </div>
                    </div>
                    <div className="card-body">
                        <h6 className="card-title text-truncate" title={reel.title}>{reel.title}</h6>
                        <div className="d-flex justify-content-between text-muted small">
                            <span>
                                <i className="ri-eye-line me-1"></i>
                                {reel.views || 0}
                            </span>
                            <span>
                                <i className="ri-heart-line me-1"></i>
                                {reel.likes || 0}
                            </span>
                            <span>
                                <i className="ri-time-line me-1"></i>
                                {reel.created_at ? new Date(reel.created_at).toLocaleDateString() : 'N/A'}
                            </span>
                        </div>
                    </div>
                </div>
            </div>
        );
    };

    const displayName = `${profileData.firstName || ''} ${profileData.lastName || ''}`.trim() || 'Seller';
    const displayEmail = profileData.email || '';
    const displayPhone = profileData.phone || 'Not provided';

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Seller Profile</h4>
                </div>
            </div>

            {/* Profile Header Card */}
            <div className="col-lg-12">
                <div className="card overflow-hidden">
                    <div className="card-body p-0">
                        <div className="bg-primary profile-bg rounded-top position-relative" style={{ height: '200px' }}>
                            <img 
                                src="/assets/images/users/avatar-1.jpg" 
                                alt={displayName} 
                                className="avatar-xl mx-auto border border-light border-3 rounded-circle position-absolute top-100 start-50 translate-middle"
                                style={{ width: '120px', height: '120px', objectFit: 'cover' }}
                            />
                        </div>
                        <div className="mt-5 px-4 pb-4">
                            <div className="text-center mb-4">
                                <h4 className="mb-2 fw-semibold">
                                    {displayName}
                                </h4>
                                <p className="text-muted mb-3">{displayEmail}</p>
                                
                                {/* Stats */}
                                <div className="row g-3 mt-4">
                                    <div className="col-lg-3 col-6">
                                        <div 
                                            className="border rounded p-3 cursor-pointer"
                                            onClick={handlePostsClick}
                                            style={{ cursor: 'pointer' }}
                                        >
                                            <h5 className="mb-1 fw-bold text-primary">{stats.posts}</h5>
                                            <p className="text-muted mb-0 small">Posts</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div className="border rounded p-3">
                                            <h5 className="mb-1 fw-bold text-primary">
                                                {stats.followers > 1000 ? (stats.followers / 1000).toFixed(1) + 'k' : stats.followers}
                                            </h5>
                                            <p className="text-muted mb-0 small">Followers</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div className="border rounded p-3">
                                            <h5 className="mb-1 fw-bold text-primary">
                                                {stats.following > 1000 ? (stats.following / 1000).toFixed(1) + 'k' : stats.following}
                                            </h5>
                                            <p className="text-muted mb-0 small">Following</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div className="border rounded p-3">
                                            <h5 className="mb-1 fw-bold text-primary">
                                                {stats.views > 1000 ? (stats.views / 1000).toFixed(1) + 'k' : stats.views}
                                            </h5>
                                            <p className="text-muted mb-0 small">Views</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Profile Content */}
                <div className="row mt-4">
                    {/* Personal Information */}
                    <div className="col-xl-4 col-lg-6">
                        <div className="card">
                            <div className="card-header bg-primary-subtle">
                                <h4 className="card-title mb-0 text-primary">
                                    <i className="ri-user-line align-middle me-2"></i>
                                    Personal Information
                                </h4>
                            </div>
                            <div className="card-body">
                                <div className="pb-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Full Name</h6>
                                    <p className="fw-medium mb-0">{displayName}</p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Email Address</h6>
                                    <p className="fw-medium mb-0">
                                        <a href={`mailto:${displayEmail}`} className="text-primary">{displayEmail}</a>
                                    </p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Phone Number</h6>
                                    <p className="fw-medium mb-0">{displayPhone}</p>
                                </div>
                                
                                <div className="pt-3">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Member Since</h6>
                                    <p className="fw-medium mb-0">
                                        {new Date().toLocaleDateString('en-US', { 
                                            year: 'numeric', 
                                            month: 'long', 
                                            day: 'numeric' 
                                        })}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Edit Profile Form */}
                    <div className="col-xl-8 col-lg-6">
                        <div className="card">
                            <div className="card-header">
                                <h5 className="card-title mb-0">Edit Profile</h5>
                            </div>
                            <div className="card-body">
                                <form onSubmit={handleSubmit}>
                                    <div className="row">
                                        <div className="col-md-8">
                                            <div className="row">
                                                <div className="col-md-6">
                                                    <div className="mb-3">
                                                        <label htmlFor="firstName" className="form-label">
                                                            First Name
                                                        </label>
                                                        <input
                                                            type="text"
                                                            className="form-control"
                                                            id="firstName"
                                                            name="firstName"
                                                            value={profileData.firstName}
                                                            onChange={handleInputChange}
                                                            disabled={loading}
                                                        />
                                                    </div>
                                                </div>
                                                <div className="col-md-6">
                                                    <div className="mb-3">
                                                        <label htmlFor="lastName" className="form-label">
                                                            Last Name
                                                        </label>
                                                        <input
                                                            type="text"
                                                            className="form-control"
                                                            id="lastName"
                                                            name="lastName"
                                                            value={profileData.lastName}
                                                            onChange={handleInputChange}
                                                            disabled={loading}
                                                        />
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="mb-3">
                                                <label htmlFor="email" className="form-label">
                                                    Email
                                                </label>
                                                <input
                                                    type="email"
                                                    className="form-control"
                                                    id="email"
                                                    name="email"
                                                    value={profileData.email}
                                                    onChange={handleInputChange}
                                                    disabled={loading}
                                                />
                                            </div>

                                            <div className="mb-3">
                                                <label htmlFor="phone" className="form-label">
                                                    Phone
                                                </label>
                                                <input
                                                    type="tel"
                                                    className="form-control"
                                                    id="phone"
                                                    name="phone"
                                                    value={profileData.phone}
                                                    onChange={handleInputChange}
                                                    disabled={loading}
                                                />
                                            </div>

                                            <div className="mb-3">
                                                <label htmlFor="bio" className="form-label">
                                                    Bio
                                                </label>
                                                <textarea
                                                    className="form-control"
                                                    id="bio"
                                                    name="bio"
                                                    rows="4"
                                                    value={profileData.bio}
                                                    onChange={handleInputChange}
                                                    disabled={loading}
                                                    placeholder="Tell us about yourself..."
                                                ></textarea>
                                            </div>
                                        </div>

                                        <div className="col-md-4">
                                            <div className="mb-3">
                                                <label className="form-label">
                                                    Profile Image
                                                </label>
                                                <div className="text-center">
                                                    <div className="mb-3">
                                                        <img 
                                                            src="/assets/images/users/avatar-1.jpg" 
                                                            alt="Profile" 
                                                            className="rounded-circle avatar-lg" 
                                                        />
                                                    </div>
                                                    <div className="input-group">
                                                        <input
                                                            type="file"
                                                            className="form-control"
                                                            accept="image/*"
                                                            onChange={handleFileChange}
                                                            disabled={loading}
                                                        />
                                                    </div>
                                                    <div className="form-text">
                                                        JPG, PNG formats allowed. Max size: 5MB
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="d-flex gap-2">
                                        <button
                                            type="button"
                                            className="btn btn-secondary"
                                            onClick={() => navigate(-1)}
                                            disabled={loading}
                                        >
                                            Cancel
                                        </button>
                                        <button
                                            type="submit"
                                            className="btn btn-primary"
                                            disabled={loading}
                                        >
                                            {loading ? (
                                                <>
                                                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                    Saving...
                                                </>
                                            ) : (
                                                'Save Changes'
                                            )}
                                        </button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Posts Section - Only show when user clicks on Posts */}
                {showPosts && (
                    <div className="row mt-4">
                        <div className="col-12">
                            <div className="card">
                                <div className="card-header d-flex align-items-center justify-content-between">
                                    <h5 className="card-title mb-0">My Posts</h5>
                                    <span className="badge bg-primary">{stats.posts} Posts</span>
                                </div>
                                <div className="card-body">
                                    {reelsLoading ? (
                                        <div className="text-center py-5">
                                            <div className="spinner-border" role="status">
                                                <span className="visually-hidden">Loading...</span>
                                            </div>
                                        </div>
                                    ) : reels.length === 0 ? (
                                        <div className="text-center py-5">
                                            <i className="ri-image-line fs-1 text-muted mb-3"></i>
                                            <h5>No Posts Yet</h5>
                                            <p className="text-muted">You haven't uploaded any reels yet.</p>
                                            <button 
                                                className="btn btn-primary"
                                                onClick={() => navigate('/studio/seller/upload')}
                                            >
                                                <i className="ri-upload-line me-1"></i> Upload Your First Reel
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="row">
                                            {reels.map(reel => renderReel(reel))}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}
